Simpler: attach onDown to each ul; on down create a state object and add window listeners (move/up). If another pointer goes down mid-drag (multi-touch), ignore while a drag is active (module-level `activeDrag`).

```js
let activeDrag = null;

function makeSortable(ul){
  const isCoarse = () => matchMedia && matchMedia('(pointer: coarse)').matches;

  ul.addEventListener('pointerdown', (e) => {
    if (activeDrag) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const li = e.target.closest('.disc-item');
    if (!li || li.parentNode !== ul) return;
    if (isCoarse() && !(li.querySelector('.disc-handle') && li.querySelector('.disc-handle').contains(e.target))) return;

    const cand = { li, ul, active:false, sx:e.clientX, sy:e.clientY, px:e.clientX, py:e.clientY };
    activeDrag = cand;

    const onMove = (ev) => {
      if (!cand.active){
        if (Math.hypot(ev.clientX - cand.sx, ev.clientY - cand.sy) < 6) return;
        if (ev.isPrimary === false) return;
        activate(cand, ev);
      }
      ev.preventDefault();
      move(cand, ev.clientX, ev.clientY);
    };
    const onUp = (ev) => {
      cleanupWindow();
      if (cand.active) finish(cand);
      activeDrag = null;
    };
    const cleanupWindow = () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
    };
    cand.cleanup = cleanupWindow;
    window.addEventListener('pointermove', onMove, {passive:false});
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  });
}
```

activate:
```js
function activate(c, ev){
  c.active = true;
  const li = c.li;
  const rect = li.getBoundingClientRect();
  c.offX = ev.clientX - rect.left;
  c.offY = ev.clientY - rect.top;
  const ph = document.createElement('li');
  ph.className = 'disc-item disc-ph';
  ph.setAttribute('aria-hidden','true');
  ph.style.height = rect.height + 'px';
  li.parentNode.insertBefore(ph, li);
  c.ph = ph;
  li.classList.add('is-dragging');
  li.style.position = 'fixed';
  li.style.left = rect.left + 'px';
  li.style.top = rect.top + 'px';
  li.style.width = rect.width + 'px';
  li.style.margin = '0';
  li.style.zIndex = 80;
  li.style.pointerEvents = 'none';
  document.documentElement.classList.add('is-grabbing');
}
```

move:
```js
function move(c, x, y){
  const li = c.li;
  li.style.left = (x - c.offX) + 'px';
  li.style.top = (y - c.offY) + 'px';
  const r = li.getBoundingClientRect();
  const center = r.top + r.height / 2;
  const items = Array.from(c.ul.children).filter(el => el !== li && el !== c.ph);
  let before = null;
  for (const it of items){
    const ir = it.getBoundingClientRect();
    if (center < ir.top + ir.height / 2){ before = it; break; }
  }
  if (c.ph.previousElementSibling !== before && c.ph.parentNode !== null){
    c.ul.insertBefore(c.ph, before || null);
  }
}
```

finish:
```js
function finish(c){
  const li = c.li, ul = c.ul, ph = c.ph;
  li.style.cssText = ''; // clear inline
  li.classList.remove('is-dragging');
  ul.insertBefore(li, ph);
  ph.remove();
  document.documentElement.classList.remove('is-grabbing');
  li.dispatchEvent(new CustomEvent('disc-reorder'));
}
```

