/* screenshots via CDP */
const { spawn } = require('node:child_process');
const http = require('node:http');
const fs = require('node:fs');
const PAGE = 'file:///tmp/disc-pi-k25iafj4/run/index.html';
const PORT = 9335;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
function httpJson(path, method = 'GET') {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port: PORT, path, method }, (res) => {
      let d = ''; res.on('data', (c) => (d += c)); res.on('end', () => resolve(JSON.parse(d)));
    });
    req.on('error', reject); req.end();
  });
}
(async () => {
  const chrome = spawn('google-chrome', ['--headless=new','--no-sandbox','--disable-gpu',
    `--remote-debugging-port=${PORT}`,'--user-data-dir=/tmp/chrome-disc-shot','about:blank'], { stdio: 'ignore' });
  try {
    let targets = null;
    for (let i = 0; i < 50; i++) { await sleep(200); try { targets = await httpJson('/json'); if (targets && targets.length) break; } catch (e) {} }
    let page;
    try { page = await httpJson('/json/new?' + encodeURIComponent('about:blank'), 'PUT'); } catch (e) { page = await httpJson('/json/new?' + encodeURIComponent('about:blank')); }
    await sleep(300);
    const ws = new WebSocket(page.webSocketDebuggerUrl);
    let nextId = 1; const pending = new Map();
    const send = (method, params) => new Promise((r) => { const id = nextId++; pending.set(id, r); ws.send(JSON.stringify({ id, method, params })); });
    ws.onmessage = (m) => { const msg = JSON.parse(m.data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg.result); pending.delete(msg.id); } };
    await new Promise((r) => (ws.onopen = r));
    await send('Runtime.enable', {});
    await send('Page.enable', {});

    async function shot(name, scale = 1) {
      const r = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true });
      fs.writeFileSync('/tmp/' + name + '.png', Buffer.from(r.data, 'base64'));
      console.log('saved /tmp/' + name + '.png');
    }
    const ev = async (expression) => {
      const r = await send('Runtime.evaluate', { expression, returnByValue: true });
      if (r && r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 300));
      return r && r.result && r.result.value;
    };

    await send('Emulation.setDeviceMetricsOverride', { width: 1400, height: 1000, deviceScaleFactor: 1, mobile: false });
    await send('Page.navigate', { url: PAGE });
    await sleep(1200);
    await shot('disc-landing');

    await ev(`document.querySelector('[data-modal-open="discWizard"]').click(); true`);
    await sleep(400);
    await shot('disc-wizard-step1');

    await ev(`(() => { let g = 0; while (g < 7) { if (document.querySelector('#btnNext') && !document.querySelector('#btnNext').hidden) { document.querySelector('#btnNext').click(); g++; } else break; } return document.querySelector('#btnFinish').hidden; })()`);
    await sleep(300);
    await shot('disc-wizard-step8');

    await ev(`document.querySelector('#btnFinish').click(); true`);
    await sleep(400);
    await shot('disc-result');

    // mobile view of wizard
    await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
    await ev(`document.querySelector('#btnRetake').click(); true`);
    await sleep(400);
    await shot('disc-mobile-wizard');

    await send('Emulation.clearDeviceMetricsOverride', {});
    ws.close();
  } finally { chrome.kill('SIGKILL'); }
})().catch((e) => { console.error('ERR', e); process.exit(1); });

