  function buildTabs(){
    TAB_LABELS.forEach((label, i) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'disc-tab' + (i === 0 ? ' is-active' : '');
      b.textContent = label;
      b.dataset.stepBtn = String(i);
      b.setAttribute('role', 'tab');
      b.setAttribute('aria-selected', i === 0 ? 'true' : 'false');
      b.tabIndex = i === 0 ? 0 : -1;
      b.addEventListener('click', () => goStep(i));
      tabsHost.appendChild(b);
      tabButtons.push(b);
    });
  }

  /* ================= navigation state ================= */
  let step = 0;
  let finished = false;

  const btnPrev   = $('#btnPrev');
  const btnNext   = $('#btnNext');
  const btnFinish = $('#btnFinish');
  const progress  = $('#discProgress');
  const stepWrap  = $('#stepWrap');
  const resultEl  = $('#discResult');
  const headTitle = $('#discHeadTitle');
  const headSub   = $('#discHeadSub');
  const headLead  = $('#discHeadLead');
  const bodyEl    = $('#discBody');
  const dialogEl  = $('.disc-dialog', $('#discWizard'));

  function centerActiveTab(){
    if (!isNarrowTabs()) return;
    const hostR = tabsHost.getBoundingClientRect();
    const tR = tabButtons[step].getBoundingClientRect();
    if (tR.width > hostR.width) return;
    tabsHost.scrollLeft += (tR.left - hostR.left) + tR.width / 2 - hostR.width / 2;
  }
  function isNarrowTabs(){ return tabsHost.scrollWidth > tabsHost.clientWidth; }

  function renderStep(){
    tabButtons.forEach((b, i) => {
      const active = i === step;
      b.classList.toggle('is-active', active);
      b.setAttribute('aria-selected', active ? 'true' : 'false');
      b.tabIndex = active ? 0 : -1;
    });
    $$('#panes .disc-pane').forEach((p, i) => p.classList.toggle('is-active', i === step));
    btnPrev.disabled = step === 0;
    btnNext.hidden = step === STEP_COUNT - 1;
