  document.addEventListener('keydown', (e) => {
    const li = e.target && e.target.closest ? e.target.closest('li.disc-item') : null;
    if (!li) return;
    const ul = li.parentNode;
    if (e.key === 'ArrowUp' && li.previousElementSibling){
      e.preventDefault();
      ul.insertBefore(li, li.previousElementSibling);
      li.focus();
    } else if (e.key === 'ArrowDown' && li.nextElementSibling){
      e.preventDefault();
      li.nextElementSibling.after(li);
      li.focus();
    }
  });

