  'svg icons only': (s.match(/<svg/g)||[]).length >= 10 && !s.includes('<img '),
  'offline file:// safe': !s.includes('fetch(') && !s.includes('XMLHttpRequest') && !s.includes('new Worker'),
};
let fail = 0;
for (const [k,v] of Object.entries(checks)) { console.log((v?'PASS':'FAIL'), k); if(!v) fail++; }
